import AppKit

// A replica of the editor's responder shape: a root view that takes first
// responder (FileDropView) and a canvas overlay inside it that also accepts
// it (CanvasOverlayView). The overlay only sees a key when it is first
// responder; the root stands for everything from the content view up.
var log: [String] = []

final class Overlay: NSView {
    override var acceptsFirstResponder: Bool { true }
    override func keyDown(with event: NSEvent) {
        log.append("overlay keyCode \(event.keyCode)")
    }
}

final class Root: NSView {
    override var acceptsFirstResponder: Bool { true }
    override func keyDown(with event: NSEvent) {
        log.append("root keyCode \(event.keyCode)")
    }
}

func key(_ code: UInt16, _ text: String, window: NSWindow) -> NSEvent {
    NSEvent.keyEvent(
        with: .keyDown, location: .zero, modifierFlags: [], timestamp: 0,
        windowNumber: window.windowNumber, context: nil, characters: text,
        charactersIgnoringModifiers: text, isARepeat: false, keyCode: code)!
}

_ = NSApplication.shared
let window = NSWindow(
    contentRect: NSRect(x: 0, y: 0, width: 200, height: 200), styleMask: [.titled],
    backing: .buffered, defer: false)
let root = Root(frame: NSRect(x: 0, y: 0, width: 200, height: 200))
let overlay = Overlay(frame: NSRect(x: 10, y: 10, width: 100, height: 100))
root.addSubview(overlay)
window.contentView = root

window.makeFirstResponder(root)  // viewDidAppear's makeFirstResponder(view)
window.sendEvent(key(53, "\u{1b}", window: window))
window.sendEvent(key(36, "\r", window: window))
print("root focused:", log)

log = []
window.makeFirstResponder(overlay)  // CanvasOverlayView.mouseDown
window.sendEvent(key(53, "\u{1b}", window: window))
window.sendEvent(key(36, "\r", window: window))
print("overlay focused:", log)

